import { total } from './pricing.js';
import { reserve } from './inventory.js';
import { assertOrder } from './validate.js';

// 结算入口：先做完整校验，再计算与预留库存。
// 保持原有导出签名与返回结构 {total, stock}。
export function checkout(items, stock, coupon = '') {
  assertOrder(items, coupon);
  return { total: total(items, coupon), stock: reserve(items, stock) };
}

