import { assertItems } from './validate.js';

// 预留库存：先聚合每个 sku 的累计需求并整体校验，全部通过后才生成新的库存对象。
// 失败路径与成功路径都不修改传入的 stock（原子性 + 入参不可变）。
export function reserve(items, stock) {
  assertItems(items);
  if (stock === null || typeof stock !== 'object') throw new Error('库存非法');

  const demand = new Map();
  for (const item of items) {
    demand.set(item.sku, (demand.get(item.sku) ?? 0) + item.qty);
  }

  // 校验阶段：只读，不写入。
  for (const [sku, qty] of demand) {
    if ((stock[sku] ?? 0) < qty) throw new Error('库存不足');
  }

  // 提交阶段：构造副本，避免修改调用者对象。
  const next = { ...stock };
  for (const [sku, qty] of demand) {
    next[sku] = (stock[sku] ?? 0) - qty;
  }
  return next;
}

