import { assertItems, assertCoupon } from './validate.js';

// 折扣率表：仅在已知优惠码上应用。
const DISCOUNTS = { SAVE10: 0.9 };

// 计算总价（单位：分，非负整数）。
export function total(items, coupon = '') {
  assertItems(items);
  assertCoupon(coupon);
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const rate = DISCOUNTS[coupon];
  // 折扣后四舍五入为整数分；无折扣时结果本身已是整数。
  return rate === undefined ? subtotal : Math.round(subtotal * rate);
}

