// 输入校验：集中定义 items / coupon 的合法形状，供 pricing 与 inventory 复用。
// 目标：任何非法输入都在触碰调用者的 stock 之前抛出错误（原子性）。

const KNOWN_COUPONS = new Set(['SAVE10']);

// 允许的优惠码：空字符串（不打折）或已知优惠码。
export function assertCoupon(coupon = '') {
  if (coupon === '') return coupon;
  if (typeof coupon !== 'string' || !KNOWN_COUPONS.has(coupon)) {
    throw new Error('未知优惠码');
  }
  return coupon;
}

// 价格为以分计的非负整数，数量为正整数；sku 必须为非空字符串。
export function assertItems(items) {
  if (!Array.isArray(items)) throw new Error('订单必须是数组');
  for (const item of items) {
    if (item === null || typeof item !== 'object') throw new Error('订单项非法');
    if (typeof item.sku !== 'string' || item.sku === '') throw new Error('sku 非法');
    if (!Number.isSafeInteger(item.price) || item.price < 0) throw new Error('价格非法');
    if (!Number.isSafeInteger(item.qty) || item.qty <= 0) throw new Error('数量非法');
  }
  return items;
}

// 校验整单（可选传入 coupon）。
export function assertOrder(items, coupon = '') {
  assertItems(items);
  assertCoupon(coupon);
}

