import test from 'node:test';
import assert from 'node:assert/strict';
import {checkout} from '../src/checkout.js';

// 新增用例：只补充既有验收测试未覆盖的不变量，不改动 test/checkout.test.js。

test('非法输入不修改库存', () => {
  const cases = [
    [[{sku: 'a', price: 100, qty: -1}], {a: 3}, ''],
    [[{sku: 'a', price: 1.2, qty: 1}], {a: 3}, ''],
    [[{sku: 'a', price: 100, qty: 1}], {a: 3}, 'BAD'],
    [[{sku: 'a', price: 100, qty: 1.5}], {a: 3}, ''],
    [[{sku: '', price: 100, qty: 1}], {a: 3}, ''],
    [[{sku: 'a', price: -5, qty: 1}], {a: 3}, ''],
  ];
  for (const [items, stock, coupon] of cases) {
    const before = {...stock};
    assert.throws(() => checkout(items, stock, coupon));
    assert.deepEqual(stock, before);
  }
});

test('库存不足时 stock 不被改动且报错', () => {
  const stock = {a: 1};
  assert.throws(() => checkout([{sku: 'a', price: 100, qty: 2}], stock), /库存不足/);
  assert.deepEqual(stock, {a: 1});
});

test('返回的 stock 是副本，改动它不影响入参', () => {
  const stock = {a: 3};
  const r = checkout([{sku: 'a', price: 100, qty: 2}], stock);
  assert.notEqual(r.stock, stock);
  r.stock.a = 999;
  r.stock.b = 1;
  assert.deepEqual(stock, {a: 3});
});

test('成功时入参 items 不被修改', () => {
  const items = [{sku: 'a', price: 100, qty: 2}];
  const snapshot = JSON.parse(JSON.stringify(items));
  checkout(items, {a: 5});
  assert.deepEqual(items, snapshot);
});

test('空优惠码等于不打折', () => {
  assert.equal(checkout([{sku: 'a', price: 101, qty: 1}], {a: 3}, '').total, 101);
  assert.equal(checkout([{sku: 'a', price: 101, qty: 1}], {a: 3}).total, 101);
});

test('SAVE10 按分四舍五入（0.5 分进位）', () => {
  // 100 * 0.9 = 90 -> 90；105 * 0.9 = 94.5 -> 95；104 * 0.9 = 93.6 -> 94
  assert.equal(checkout([{sku: 'a', price: 100, qty: 1}], {a: 3}, 'SAVE10').total, 90);
  assert.equal(checkout([{sku: 'a', price: 105, qty: 1}], {a: 3}, 'SAVE10').total, 95);
  assert.equal(checkout([{sku: 'a', price: 104, qty: 1}], {a: 3}, 'SAVE10').total, 94);
});

test('多 SKU 与重复 SKU 的库存扣减正确', () => {
  const stock = {a: 5, b: 2};
  const r = checkout(
    [{sku: 'a', price: 10, qty: 1}, {sku: 'b', price: 20, qty: 1}, {sku: 'a', price: 10, qty: 2}],
    stock,
  );
  assert.equal(r.total, 10 + 20 + 20);
  assert.deepEqual(r.stock, {a: 2, b: 1});
  assert.deepEqual(stock, {a: 5, b: 2});
});

test('未知 sku 视为零库存', () => {
  assert.throws(() => checkout([{sku: 'zzz', price: 10, qty: 1}], {a: 3}), /库存不足/);
});

test('拒绝非数组订单与空订单不打折', () => {
  assert.throws(() => checkout(null, {a: 3}));
  assert.equal(checkout([], {a: 3}, 'SAVE10').total, 0);
});

test('拒绝非安全整数与布尔值输入', () => {
  assert.throws(() => checkout([{sku: 'a', price: Number.MAX_SAFE_INTEGER + 2, qty: 1}], {a: 3}));
  assert.throws(() => checkout([{sku: 'a', price: true, qty: 1}], {a: 3}));
  assert.throws(() => checkout([{sku: 'a', price: 100, qty: 0}], {a: 3}));
  assert.throws(() => checkout([{sku: 'a', price: 100, qty: '2'}], {a: 3}));
});

test('零价商品合法且不改变库存语义', () => {
  const r = checkout([{sku: 'a', price: 0, qty: 2}], {a: 3});
  assert.equal(r.total, 0);
  assert.deepEqual(r.stock, {a: 1});
});
